-- crash-edit/delete-person
-- Removes a person (admins only). The history keeps their last version, so nothing is lost.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

delete
from "persons"
where "persons"."id" = $1
returning "id", "crash_id", "slug", "status", "name_en", "name_np", "age", "sex", "road_user", "hometown_text", "name_visibility", "publication", "version", "created_at", "updated_at";
